@using sv_3594840fb56e4760b0251f60106d4420.Services

<div class="settings-section">
    <h2>Notification Preferences</h2>

    <div class="toggle-group">
        <label class="toggle-item">
            <span>Email Notifications</span>
            <input type="checkbox" @bind="EmailNotifications" class="toggle-switch" />
        </label>

        <label class="toggle-item">
            <span>Push Notifications</span>
            <input type="checkbox" @bind="PushNotifications" class="toggle-switch" />
        </label>

        <label class="toggle-item">
            <span>Weekly Digest</span>
            <input type="checkbox" @bind="WeeklyDigest" class="toggle-switch" />
        </label>
    </div>

    <div class="channel-list">
        <h3>Muted Channels</h3>
        @foreach (var channel in AvailableChannels)
        {
            <label class="channel-item">
                <input type="checkbox"
                       checked="@MutedChannels.Contains(channel)"
                       @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                <span>@channel</span>
            </label>
        }
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync">Save Preferences</button>
    </div>

    @if (ShowSuccess)
    {
        <div class="toast success">Preferences saved successfully!</div>
    }
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool EmailNotifications;
    private bool PushNotifications;
    private bool WeeklyDigest;
    private List<string> MutedChannels = new();
    private bool ShowSuccess;
    private bool _initialized;

    private static readonly string[] AvailableChannels = { "General", "Announcements", "Engineering", "Design", "Marketing", "Support" };

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !_initialized)
        {
            EmailNotifications = Prefs.EmailNotifications;
            PushNotifications = Prefs.PushNotifications;
            WeeklyDigest = Prefs.WeeklyDigest;
            MutedChannels = new List<string>(Prefs.MutedChannels);
            _initialized = true;
        }
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted && !MutedChannels.Contains(channel))
            MutedChannels.Add(channel);
        else if (!muted)
            MutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        var updated = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, new List<string>(MutedChannels));
        await OnSave.InvokeAsync(updated);
        ShowSuccess = true;
        StateHasChanged();
        await Task.Delay(3000);
        ShowSuccess = false;
    }
}
"}

{"path": "/tmp/sv-3594840fb56e4760b0251f60106d4420/Components/Pages/Settings/SecuritySection.razor", "file_text": "@namespace sv_3594840fb56e4760b0251f60106d4420.Components.Pages.Settings
@using sv_3594840fb56e4760b0251f60106d4420.Services

<div class="settings-section">
    <h2>Security Settings</h2>

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => PasswordPanelOpen = !PasswordPanelOpen">
            <span>Change Password</span>
            <span class="expand-icon">@(PasswordPanelOpen ? "▼" : "▶")</span>
        </button>

        @if (PasswordPanelOpen)
        {
            <div class="panel-content">
                <div class="form-group">
                    <label for="currentPassword">Current Password</label>
                    <input id="currentPassword" type="password" @bind="CurrentPassword" />
                </div>
                <div class="form-group">
                    <label for="newPassword">New Password</label>
                    <input id="newPassword" type="password" @bind="NewPassword" />
                </div>
                <div class="form-group">
                    <label for="confirmPassword">Confirm Password</label>
                    <input id="confirmPassword" type="password" @bind="ConfirmPassword" />
                </div>
                @if (!string.IsNullOrEmpty(PasswordError))
                {
                    <div class="error-message">@PasswordError</div>
                }
                @if (PasswordSuccess)
                {
                    <div class="toast success">Password updated successfully!</div>
                }
                <button class="btn btn-primary" @onclick="ChangePasswordAsync">Update Password</button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="tfa-section">
        <h3>Two-Factor Authentication</h3>
        <div class="tfa-status">
            <span class="status-indicator @(TwoFactorEnabled ? "enabled" : "disabled")">
                @(TwoFactorEnabled ? "✓ Enabled" : "✗ Disabled")
            </span>
            <label class="toggle-item">
                <span>Enable 2FA</span>
                <input type="checkbox" @bind="TwoFactorEnabled" class="toggle-switch" />
            </label>
        </div>
        @if (Security?.LastPasswordChange is not null)
        {
            <p class="info-text">Last password change: @Security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }
    </div>

    <!-- Active Sessions -->
    <div class="sessions-section">
        <h3>Active Sessions</h3>
        @if (Security?.Sessions is { Count: > 0 })
        {
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Security.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session != Security.Sessions.FirstOrDefault())
                                {
                                    <button class="btn btn-danger btn-sm"
                                            @onclick="() => ShowRevokeConfirmation(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        }
        else
        {
            <p>No active sessions found.</p>
        }
    </div>

    <!-- Revoke Confirmation Dialog -->
    @if (SessionToRevoke is not null)
    {
        <div class="modal-overlay" @onclick="CancelRevoke">
            <div class="modal-dialog" @onclick:stopPropagation="true">
                <h3>Revoke Session</h3>
                <p>Are you sure you want to revoke the session on <strong>@SessionToRevoke.Device</strong> from <strong>@SessionToRevoke.Location</strong>?</p>
                <div class="modal-actions">
                    <button class="btn btn-danger" @onclick="ConfirmRevokeAsync">Revoke</button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public SecuritySettings? Security { get; set; }
    [Parameter] public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool PasswordPanelOpen;
    private string CurrentPassword = "";
    private string NewPassword = "";
    private string ConfirmPassword = "";
    private string? PasswordError;
    private bool PasswordSuccess;
    private bool TwoFactorEnabled;
    private ActiveSession? SessionToRevoke;
    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (Security is not null && !_initialized)
        {
            TwoFactorEnabled = Security.TwoFactorEnabled;
            _initialized = true;
        }
    }

    private async Task ChangePasswordAsync()
    {
        PasswordError = null;
        PasswordSuccess = false;

        if (string.IsNullOrWhiteSpace(CurrentPassword))
        {
            PasswordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(NewPassword))
        {
            PasswordError = "New password is required.";
            return;
        }
        if (NewPassword != ConfirmPassword)
        {
            PasswordError = "New password and confirmation do not match.";
            return;
        }

        await OnChangePassword.InvokeAsync((CurrentPassword, NewPassword));
        PasswordSuccess = true;
        CurrentPassword = "";
        NewPassword = "";
        ConfirmPassword = "";
        StateHasChanged();
        await Task.Delay(3000);
        PasswordSuccess = false;
    }

    private void ShowRevokeConfirmation(ActiveSession session)
    {
        SessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        SessionToRevoke = null;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (SessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(SessionToRevoke.Id);
            SessionToRevoke = null;
        }
    }
}
"}

{"path": "/tmp/sv-3594840fb56e4760b0251f60106d4420/Components/Pages/Settings/AppearanceSection.razor", "file_text": "@namespace sv_3594840fb56e4760b0251f60106d4420.Components.Pages.Settings
@using sv_3594840fb56e4760b0251f60106d4420.Services

<div class="settings-section">
    <h2>Appearance Settings</h2>

    <div class="form-group">
        <label>Theme</label>
        <div class="radio-group">
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <label class="radio-item">
                    <input type="radio" name="theme" value="@theme"
                           checked="@(Theme == theme)"
                           @onchange="() => Theme = theme" />
                    <span>@theme</span>
                </label>
            }
        </div>
    </div>

    <div class="form-group">
        <label>Font Size</label>
        <div class="radio-group">
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="@size"
                           checked="@(FontSize == size)"
                           @onchange="() => FontSize = size" />
                    <span>@size</span>
                </label>
            }
        </div>
    </div>

    <div class="form-group">
        <label for="language">Language</label>
        <select id="language" @bind="Language">
            <option value="en">English</option>
            <option value="es">Español</option>
            <option value="fr">Français</option>
            <option value="de">Deutsch</option>
            <option value="ja">日本語</option>
            <option value="zh">中文</option>
        </select>
    </div>

    <div class="toggle-group">
        <label class="toggle-item">
            <span>Compact Mode</span>
            <input type="checkbox" @bind="CompactMode" class="toggle-switch" />
        </label>
    </div>

    <!-- Live Preview -->
    <div class="preview-area @GetPreviewClasses()">
        <h4>Live Preview</h4>
        <p class="preview-text">This is how your content will look with the selected settings.</p>
        <div class="preview-card">
            <strong>Sample Card</strong>
            <p>Here is some preview content that reflects your appearance choices.</p>
            <button class="btn btn-primary">Sample Button</button>
        </div>
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync">Save</button>
    </div>

    @if (ShowSuccess)
    {
        <div class="toast success">Appearance settings saved!</div>
    }
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string Theme = "System";
    private string FontSize = "Medium";
    private string Language = "en";
    private bool CompactMode;
    private bool ShowSuccess;
    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_initialized)
        {
            Theme = Settings.Theme;
            FontSize = Settings.FontSize;
            Language = Settings.Language;
            CompactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = $"theme-{Theme.ToLowerInvariant()} font-{FontSize.ToLowerInvariant()}";
        if (CompactMode) classes += " compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        var updated = new AppearanceSettings(Theme, FontSize, Language, CompactMode);
        await OnSave.InvokeAsync(updated);
        ShowSuccess = true;
        StateHasChanged();
        await Task.Delay(3000);
        ShowSuccess = false;
    }
}
"}

