toolArgs.file_text:
/* Settings Dashboard Styles */

.settings-layout {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background: var(--sidebar-bg, #f8f9fa);
    border-right: 1px solid var(--border-color, #e0e0e0);
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.875rem 1.5rem;
    cursor: pointer;
    transition: all 0.2s ease;
    border-left: 3px solid transparent;
    color: var(--text-muted, #6c757d);
}

.settings-nav-item:hover {
    background: var(--hover-bg, #e9ecef);
    color: var(--text-color, #212529);
}

.settings-nav-item.active {
    background: var(--active-bg, #e7f1ff);
    border-left-color: var(--primary-color, #0d6efd);
    color: var(--primary-color, #0d6efd);
    font-weight: 600;
}

.nav-icon {
    font-size: 1.2rem;
}

/* Main Content */
.settings-content {
    flex: 1;
    padding: 2rem 3rem;
    max-width: 800px;
}

.settings-section h2 {
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    font-weight: 600;
    color: var(--text-color, #212529);
}

.settings-section h3 {
    margin: 1.5rem 0 1rem;
    font-size: 1.1rem;
    font-weight: 600;
}

/* Form Controls */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.375rem;
    font-weight: 500;
    font-size: 0.875rem;
    color: var(--label-color, #495057);
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="url"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.625rem 0.875rem;
    border: 1px solid var(--border-color, #ced4da);
    border-radius: 6px;
    font-size: 0.9375rem;
    transition: border-color 0.2s;
    background: var(--input-bg, #fff);
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: var(--primary-color, #0d6efd);
    box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.15);
}

/* Buttons */
.btn {
    padding: 0.625rem 1.25rem;
    border: none;
    border-radius: 6px;
    font-size: 0.875rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-primary {
    background: var(--primary-color, #0d6efd);
    color: #fff;
}

.btn-primary:hover {
    background: #0b5ed7;
}

.btn-secondary {
    background: var(--secondary-bg, #6c757d);
    color: #fff;
}

.btn-secondary:hover {
    background: #5c636a;
}

.btn-danger {
    background: #dc3545;
    color: #fff;
}

.btn-danger:hover {
    background: #bb2d3b;
}

.btn-sm {
    padding: 0.375rem 0.75rem;
    font-size: 0.8rem;
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

/* Avatar */
.avatar-preview {
    display: flex;
    align-items: center;
    gap: 1.5rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    border: 1px solid var(--border-color, #e0e0e0);
    border-radius: 8px;
    background: var(--card-bg, #f8f9fa);
}

.avatar-image {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    overflow: hidden;
    background: var(--primary-color, #0d6efd);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

.avatar-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    color: #fff;
    font-size: 2rem;
    font-weight: 600;
}

.avatar-url {
    flex: 1;
}

.avatar-url label {
    display: block;
    margin-bottom: 0.375rem;
    font-weight: 500;
    font-size: 0.875rem;
}

.avatar-url input {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid var(--border-color, #ced4da);
    border-radius: 6px;
    font-size: 0.875rem;
}

/* Toggle Switches */
.toggle-group {
    margin-bottom: 1.5rem;
}

.toggle-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.875rem 1rem;
    border: 1px solid var(--border-color, #e0e0e0);
    border-radius: 6px;
    margin-bottom: 0.5rem;
    cursor: pointer;
}

.toggle-item:hover {
    background: var(--hover-bg, #f8f9fa);
}

.toggle-switch {
    width: 3rem;
    height: 1.5rem;
    cursor: pointer;
}

/* Channel List */
.channel-list {
    margin-top: 1.5rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.625rem 1rem;
    border-bottom: 1px solid var(--border-color, #f0f0f0);
    cursor: pointer;
}

.channel-item:hover {
    background: var(--hover-bg, #f8f9fa);
}

/* Expandable Panel */
.expandable-panel {
    border: 1px solid var(--border-color, #e0e0e0);
    border-radius: 8px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1rem 1.25rem;
    background: var(--card-bg, #f8f9fa);
    border: none;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;
}

.panel-header:hover {
    background: var(--hover-bg, #e9ecef);
}

.panel-content {
    padding: 1.25rem;
    border-top: 1px solid var(--border-color, #e0e0e0);
}

/* 2FA Section */
.tfa-section {
    margin-bottom: 1.5rem;
    padding: 1rem;
    border: 1px solid var(--border-color, #e0e0e0);
    border-radius: 8px;
}

.tfa-status {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.status-indicator {
    font-weight: 600;
    font-size: 0.875rem;
}

.status-indicator.enabled {
    color: #198754;
}

.status-indicator.disabled {
    color: #dc3545;
}

.info-text {
    font-size: 0.8125rem;
    color: var(--text-muted, #6c757d);
    margin-top: 0.5rem;
}

/* Sessions Table */
.sessions-section {
    margin-top: 1.5rem;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.875rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.75rem 1rem;
    text-align: left;
    border-bottom: 1px solid var(--border-color, #e0e0e0);
}

.sessions-table th {
    font-weight: 600;
    background: var(--card-bg, #f8f9fa);
}

.current-badge {
    font-size: 0.75rem;
    padding: 0.25rem 0.5rem;
    background: #e7f1ff;
    color: var(--primary-color, #0d6efd);
    border-radius: 4px;
    font-weight: 500;
}

/* Modal */
.modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: #fff;
    border-radius: 12px;
    padding: 2rem;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
}

.modal-dialog h3 {
    margin: 0 0 1rem;
}

.modal-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
    justify-content: flex-end;
}

/* Radio Group */
.radio-group {
    display: flex;
    gap: 1.5rem;
    margin-top: 0.5rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

/* Preview Area */
.preview-area {
    margin-top: 1.5rem;
    padding: 1.5rem;
    border: 2px dashed var(--border-color, #ced4da);
    border-radius: 8px;
    transition: all 0.3s ease;
}

.preview-area h4 {
    margin: 0 0 0.75rem;
    font-size: 0.875rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--text-muted, #6c757d);
}

.preview-card {
    padding: 1rem;
    border: 1px solid var(--border-color, #e0e0e0);
    border-radius: 6px;
    margin-top: 1rem;
}

/* Theme Preview Variants */
.preview-area.theme-dark {
    background: #1e1e2e;
    color: #cdd6f4;
    border-color: #45475a;
}

.preview-area.theme-dark .preview-card {
    background: #313244;
    border-color: #45475a;
}

.preview-area.theme-light {
    background: #ffffff;
    color: #212529;
}

.preview-area.theme-system {
    background: #f8f9fa;
    color: #212529;
}

/* Font Size Preview Variants */
.preview-area.font-small .preview-text {
    font-size: 0.8rem;
}

.preview-area.font-medium .preview-text {
    font-size: 1rem;
}

.preview-area.font-large .preview-text {
    font-size: 1.2rem;
}

/* Compact Mode Preview */
.preview-area.compact {
    padding: 0.75rem;
}

.preview-area.compact .preview-card {
    padding: 0.5rem;
}

/* Toast */
.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    font-size: 0.875rem;
    font-weight: 500;
    animation: slideIn 0.3s ease;
}

.toast.success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

.error-message {
    color: #dc3545;
    font-size: 0.8125rem;
    margin-bottom: 0.75rem;
}

.loading {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 4rem;
    color: var(--text-muted, #6c757d);
    font-size: 1.1rem;
}

@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateY(-10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

